    "text": "\r\n\r\n    $ \"C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>\\<DIR>\" -Command \"rg -n -i \\\"login|password|account\\\\.xiaomi|serviceLogin\\\" C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>\\<DIR> C:\\<DIR>\\<DIR>\\<DIR>\\<DIR> C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>\\<DIR>\"\"'!*.map\" | Select-Object -First 80'\r\n    status: Completed · exit 0\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>:163:| 密码 | `admin`（`config.json` → `admin_password`） |\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>:173:  -d '{\"admin_password\":\"你的新密码\",\"api_keys\":\"sk-新key\"}'\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>:213:`serviceToken` / `userId` / `xiaomichatbot_ph` / `admin_password` 落盘时用 **Fernet** 加密（`enc:v1:` 前缀），密钥在同目录 **`.secret_key`**。\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>:1008:  \"admin_password\": \"enc:v1:gAAAAA...\",\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>:1015:      \"login_time\": \"04-26 17:00\",\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>\\<DIR>:1249:            \"login_time\": acc.login_time,\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>\\<DIR>:1327:                    login_time=now, is_valid=True,\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>\\<DIR>:1335:                login_time=now, is_valid=True,\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>\\<DIR>:262:                        <input type=\"password\" id=\"adminPassword\" data-i18n-placeholder=\"adminPwdPH\" placeholder=\"默认 admin，修改后刷新需重新登录\">\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>\\<DIR>:307:en:{\"curl\":\"cURL\",\"cookie\":\"Cookie\",\"accounts\":\"Accounts\",\"apikey\":\"API Key\",\"usage\":\"Usage\",\"parseCurl\":\"Parse cURL\",\"parseFill\":\"Parse & Fill ↓\",\"saveAcct\":\"Save Account\",\"verifyBtn\":\"Verifying...\",\"saved\":\"Saved\",\"saveFail\":\"Save Failed\",\"reqFail\":\"Request Failed\",\"refresh\":\"Refresh\",\"testAll\":\"Test All\",\"cleanupSessions\":\"Cleanup Old Sessions\",\"noAccts\":\"No accounts configured\",\"valid\":\"✅ Active\",\"notVerified\":\"⚪ Not Verified\",\"test\":\"Test\",\"delete\":\"Delete\",\"loadFail\":\"Load Failed\",\"testing\":\"Testing...\",\"testFail\":\"Test Failed\",\"noAcctTest\":\"No accounts to test\",\"allTestDone\":\"valid\",\"cleanup\":\"Cleaning...\",\"cleanupFail\":\"Cleanup failed: \",\"unknown\":\"unknown\",\"deleteConfirm\":\"Delete this account?\",\"deleted\":\"Deleted\",\"deleteFail\":\"Delete Failed\",\"usageNoData\":\"No usage data\",\"usageModel\":\"Model\",\"usageReqs\":\"Requests\",\"usageInput\":\"Input\",\"usageOutput\":\"Output\",\"usageTotal\":\"Total\",\"usageSum\":\"📋 Total\",\"usageLoadFail\":\"Load failed: \",\"periodAll\":\"All\",\"periodWeek\":\"This Week\",\"periodToday\":\"Today\",\"clearConfirm\":\"Clear all usage data? This cannot be undone.\",\"cleared\":\"Cleared\",\"clearFail\":\"Clear failed\",\"configSaved\":\"Config saved\",\"saveConfigFail\":\"Save failed\",\"parseFail\":\"Parse failed, check cURL format\",\"parsing\":\"Parsing...\",\"parseOk\":\"Parsed\",\"testConn\":\"Test Connection\",\"addAcct\":\"Add Account\",\"connOk\":\"Connected: \",\"connFail\":\"Connection failed: \",\"acctAdded\":\"Account added\",\"pasteCurl\":\"Please paste cURL command\",\"pasteCookie\":\"Please paste Cookie string\",\"fieldsRequired\":\"Please fill all fields\",\"filledFields\":\"Filled\",\"filledFields2\":\"field(s)\",\"filledFields3\":\"missing\",\"filledFields4\":\"\",\"noValidFields\":\"No valid fields found\",\"apiKeysLabel\":\"Separate multiple keys with commas\",\"apiKeysPH\":\"sk-key1, sk-key2, sk-key3\",\"saveConfig\":\"Save Config\",\"mimoDesc\":\"Xiaomi MiMo OpenAI-compatible API\",\"keysSaved\":\"Config saved\",\"saving\":\"Saving...\",\"passthroughLabel\":\"Tool Passthrough Mode\",\"passthroughHint\":\"Skip format instructions, embed raw tool definitions (suitable for Roo Code / Cline)\",\"adminPwdLabel\":\"Admin Password\",\"adminPwdPH\":\"Default admin, refresh to re-login after change\",\"compressModeLabel\":\"Context Compression Mode\",\"compressModeHint\":\"ON=LLM summary compression (preserves key info), OFF=sliding window truncation (drops old messages). Both trigger at 80% threshold.\",\"howToGet\":\"How to get?\",\"step1\":\"Login \",\"step2\":\"Press F12 → Network tab\",\"step3\":\"Send a message, find the \",\"step4\":\"Right-click → Copy as cURL, paste below\",\"cookieHint\":\"Get these 3 values from browser Cookies:\",\"cookiePH\":\"Paste full cookie, e.g: serviceToken=\\\"xxx\\\"; userId=\\\"123\\\"; xiaomichatbot_ph=\\\"abc\\\"\",\"pasteOrFill\":\"Paste or auto-fill from above\",\"refresh2\":\"Refresh\",\"clearUsage\":\"Clear\",\"cookiePH2\":\"Paste full cookie, e.g: serviceToken=\\\"xxx\\\"; userId=123; xiaomichatbot_ph=\\\"yyy\\\"\",\"pasteST\":\"Paste serviceToken\",\"pasteUID\":\"Paste userId\",\"pastePH\":\"Paste xiaomichatbot_ph\",\"parseFailMsg\":\"Parse failed, check cURL format\",\"parseOkMsg\":\"Parsed\",\"testConnBtn\":\"Test Connection\",\"addAcctBtn\":\"Add Account\",\"reqFailMsg\":\"Request failed\",\"connOkMsg\":\"Connected: \",\"connFailMsg\":\"Connection failed: \",\"filledMsg\":\"Filled \",\"filledMsg2\":\" field(s)\",\"filledMsg3\":\" (missing \",\"filledMsg4\":\")\",\"noValidFieldsMsg\":\"No valid fields found\",\"fieldsRequiredMsg\":\"Please fill all fields\",\"saveFailMsg\":\"Save failed\",\"noAcctsMsg\":\"No accounts configured\",\"loadFailMsg\":\"Load failed\",\"testingMsg\":\"Testing...\",\"validMsg\":\"✅ Active: \",\"cleanupFailMsg\":\"Cleanup failed: \",\"noDataMsg\":\"No usage data\",\"clearFailMsg\":\"Clear failed: \",\"allValidMsg\":\" valid\",\"testingBtn\":\"Test\",\"deleteBtn\":\"Delete\",\"unknown\":\"unknown\",\"cookieHint2\":\"Or paste the full Cookie string (separated by ;), click \\\"Parse & Fill\\\" to auto-split\"}};\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>\\<DIR>:343:                $id('adminPassword').value = cfg.admin_password || '';\r\n      C:\\<DIR>\\<DIR>\\<DIR>\\<DIR>\\<DIR>:352:            cfg.admin_password = $id('adminPassword').value || 'admin';\r\n\r\n",
